solution:
PHASES = ["préparation", "détection", "confinement", "éradication", "rétablissement", "retour d’expérience"]

def etape_suivante(etape):
    i = PHASES.index(etape)
    if i + 1 == len(PHASES):
        return "terminé"
    return PHASES[i + 1]

def gravite(personnes, sensibles, arret):
    score = (2 if sensibles else 0) + (2 if arret else 0) + (1 if personnes >= 50 else 0)
    if score >= 4:
        return "critique"
    if score >= 2:
        return "majeure"
    return "mineure"

def minutes(heure):
    h, m = heure.split(":")
    return int(h) * 60 + int(m)

def fiche(evenements, personnes, sensibles, arret):
    tries = sorted(evenements)
    debut, fin = tries[0][0], tries[-1][0]
    return {
        "gravité": gravite(personnes, sensibles, arret),
        "début": debut,
        "fin": fin,
        "durée_min": minutes(fin) - minutes(debut),
        "chronologie": [h + " " + t for h, t in tries],
    }
